onst locId = location.value?.id;\n  if (!locId) return '';\n  const loc = graph.value.locations.find(l => l.id === locId);\n  return loc?.brief || '';\n});\n\nconst ownerNames = computed(() => {\n  const names = new Set<string>();\n  const un = userName.value?.trim();\n  if (un) names.add(un);\n  PLAYER_OWNER_NAMES.forEach(n => names.add(n));\n  return Array.from(names);\n});\n\nconst items = computed<OwnedItem[]>(() => getItemsBelongingTo(graph.value, ownerNames.value));\n\nconst defaultOwner = computed(() => userName.value || '{{user}}');\n\nconst showItemModal = ref(false);\nconst itemModalMode = ref<'edit' | 'add'>('add');\nconst editingItem = ref<OwnedItem | undefined>(undefined);\n\nfunction onEditItem(item: OwnedItem) {\n  editingItem.value = item;\n  itemModalMode.value = 'edit';\n  showItemModal.value = true;\n}\n\nfunction onAddItem() {\n  editingItem.value = undefined;\n  itemModalMode.value = 'add';\n  showItemModal.value = true;\n}\n\n// 从知识图谱中删除指定物品（深拷贝 → splice → 清旧边 → 提交）\nfunction onDeleteItem(item: OwnedItem) {\n  const g = graph.value;\n  const next: KnowledgeGraph = JSON.parse(JSON.stringify(g));\n  const idx = next.items.findIndex(i => i.id === item.item.id);\n  if (idx < 0) return;\n  next.items.splice(idx, 1);\n  const itemId = item.item.id;\n  next.edges = (next.edges || []).filter(e => !(e.type === 'belongs_to' && e.from === itemId));\n  next.updatedAt = new Date().toISOString();\n  store.setKnowledgeGraphWithoutHistory(next);\n}\n\nconst isEditingLoc = ref(false);\nconst locSelect = ref('');\nconst locCustom = ref('');\n\nconst avatarStyle = computed(() => ({\n  background: 'rgba(var(--zn-accent-rgb), 0.75)',\n  color: '#fff',\n}));\n\nfunction startEditLoc() {\n  isEditingLoc.value = true;\n  const currentName = location.value?.name || '';\n  const exists = locations.value.some(l => l.name === currentName);\n  locSelect.value = exists ? currentName : (currentName ? '__custom__' : '');\n  locCustom.value = currentName;\n}\n\nfunction onLocSelectChange() {\n  if (locSelect.value !== '__custom__') {\n    locCustom.value = locSelect.value;\n  }\n}\n\nfunction saveLoc() {\n  const name = locSelect.value === '__custom__' ? locCustom.value.trim() : locSelect.value.trim();\n  if (name) {\n    store.setCharacterLocation(userName.value || '{{user}}', name);\n  }\n  isEditingLoc.value = false;\n  locSelect.value = '';\n  locCustom.value = '';\n}\n\nfunction cancelEditLoc() {\n  isEditingLoc.value = false;\n  locSelect.value = '';\n  locCustom.value = '';\n}\n</script>\n\n<style scoped>\n.wt-panel {\n  display: flex;\n  flex-direction: column;\n  gap: var(--zn-space-3);\n  flex: 1;\n  min-height: 0;\n  overflow-y: auto;\n  padding: 10px 12px;\n}\n.player-card {\n  display: flex;\n  gap: 12px;\n  align-items: flex-start;\n  background: var(--zn-bg-surface1);\n  border: 1px solid var(--zn-border-light);\n  border-radius: 8px;\n  padding: 10px 12px;\n}\n.player-avatar {\n  width: 56px;\n  height: 56px;\n  border-radius: 50%;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  font-size: 22px;\n  font-weight: 600;\n  flex-shrink: 0;\n}\n.player-info {\n  flex: 1;\n  min-width: 0;\n  display: flex;\n  flex-direction: column;\n  gap: 4px;\n}\n.player-name {\n  font-size: 16px;\n  font-weight: 600;\n  color: var(--zn-text-primary);\n}\n.player-location-row {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  font-size: 12px;\n  flex-wrap: wrap;\n}\n.player-location-label {\n  color: var(--zn-text-muted);\n}\n.player-location-value {\n  color: var(--zn-text-primary);\n  font-weight: 500;\n}\n.player-loc-brief {\n  font-size: 11px;\n  color: var(--zn-text-secondary);\n  line-height: 1.4;\n  max-width: 100%;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  display: -webkit-box;\n  -webkit-line-clamp: 2;\n  -webkit-box-orient: vertical;\n}\n.player-loc-btn {\n  font-size: 10px;\n  padding: 1px 7px;\n  border-radius: 4px;\n  border: 1px solid var(--zn-border-light);\n  background: var(--zn-bg-